328	+//! Execution of the resolved deferred tool calls of a resume.
329	+//!
330	+//! The agent runs these calls before its first turn. They take the normal
331	+//! tool-execution path without `PreToolUse`: a `Denied` call gets the denial
332	+//! result, and an `Approved` call runs after the permission re-check.
333	+
334	+use std::num::NonZeroUsize;
335	+use std::sync::{Arc, Mutex};
336	+
337	+use tracing::Instrument as _;
338	+
339	+use crate::context::{AskPoints, Authorization};
340	+use crate::control::Interceptors;
341	+use crate::deferral::PlannedCall;
342	+use crate::{
343	+    AgentEvent, ContentPart, HookEvent, Item, RunContext, Tool, ToolCallOutcome, ToolContext,
344	+    ToolResolution,
345	+};
346	+
347	+/// The synthetic result of a resolved call that did not run, because the
348	+/// run ended before the resume executed it.
349	+const NOT_RUN: &str = "tool call did not run: the run ended before the resume completed";
350	+
351	+/// Re-check an approved deferred call (spec §4.8). The ask points count as
352	+/// answered; the deny rules, guards, allow rules, mode and policy run again.
353	+/// Returns `Err(reason)` when the call must be denied.
354	+pub(crate) async fn recheck_approved<Ctx: Send + Sync + 'static>(
355	+    ctx: &RunContext<Ctx>,
356	+    tool: Option<&Arc<dyn Tool<Ctx>>>,
357	+    name: &str,
358	+    recorded_args: &serde_json::Value,
359	+) -> Result<(), String> {
360	+    let Some(tool) = tool else {
361	+        return Err(format!("tool no longer available: {name}"));
362	+    };
363	+    match ctx
364	+        .authorize_tool_detailed(name, tool.effect(), recorded_args, AskPoints::Answered)
365	+        .await
366	+    {
367	+        Authorization::Allow => Ok(()),
368	+        Authorization::Replace { args } if args == *recorded_args => Ok(()),
369	+        Authorization::Replace { .. } => Err("arguments changed on re-check".to_owned()),
370	+        Authorization::Deny { reason } => Err(reason),
371	+        // Unreachable with `AskPoints::Answered`; fail closed.
372	+        Authorization::Defer { .. } => Err("approval deferred again on re-check".to_owned()),
373	+    }
374	+}
375	+
376	+/// Run the resolved calls of a resume. Returns one outcome per call, in the
377	+/// order of `calls`, and the `PermissionDenied` events.
378	+pub(crate) async fn run_resolved_calls<Ctx: Send + Sync + 'static>(
379	+    tools: &[Arc<dyn Tool<Ctx>>],
380	+    calls: &[PlannedCall],
381	+    interceptors: &Interceptors<'_, Ctx>,
382	+    tool_ctx: &ToolContext<Ctx>,
383	+    limit: Option<NonZeroUsize>,
384	+    parent: &tracing::Span,
385	+) -> (Vec<ToolCallOutcome>, Vec<AgentEvent>) {
386	+    let denied_events: Mutex<Vec<AgentEvent>> = Mutex::new(Vec::new());
387	+    let ctx = interceptors.ctx;
388	+    let redact_output = ctx.redact_output();
389	+    let secrets = crate::redaction::SecretSet::from_env_and_extra(ctx.extra_secrets());
390	+
391	+    let futures = calls.iter().map(|call| {
392	+        let name = call.pending.tool().to_owned();
393	+        let call_id = call.pending.call_id().to_owned();
394	+        let args = call.pending.args().clone();
395	+        let tool = tools.iter().find(|t| t.name() == name).cloned();
396	+        let denied_events = &denied_events;
397	+        let secrets = &secrets;
398	+        let span = tracing::info_span!(
399	+            target: "paigasus::core::agent",
400	+            parent: parent,
401	+            "tool.execute",
402	+            otel.name = tracing::field::Empty,
403	+            otel.kind = "internal",
404	+            gen_ai.operation.name = "execute_tool",
405	+            gen_ai.tool.name = %name,
406	+            paigasus.tool.resumed = true,
407	+            otel.status_code = tracing::field::Empty,
408	+        );
409	+        span.record("otel.name", format!("execute_tool {name}").as_str());
410	+        async move {
411	+            let deny = |reason: String| {
412	+                denied_events
413	+                    .lock()
414	+                    .unwrap()
415	+                    .push(AgentEvent::PermissionDenied {
416	+                        tool: name.clone(),
417	+                        reason: reason.clone(),
418	+                    });
419	+                ToolCallOutcome {
420	+                    call_id: call_id.clone(),
421	+                    result: Err(format!("permission denied: {reason}")),
422	+                }
423	+            };
424	+            let tool = match &call.resolution {
425	+                ToolResolution::Denied { reason } => return deny(reason.clone()),
426	+                ToolResolution::Approved => {
427	+                    match recheck_approved(ctx, tool.as_ref(), &name, &args).await {
428	+                        Err(reason) => return deny(reason),
429	+                        Ok(()) => match tool {
430	+                            Some(tool) => tool,
431	+                            None => return deny(format!("tool no longer available: {name}")),
432	+                        },
433	+                    }
434	+                }
435	+            };
436	+
437	+            let result = match tool.invoke(tool_ctx, args).await {
438	+                Ok(output) => {
439	+                    let post = interceptors
440	+                        .fire(&HookEvent::PostToolUse {
441	+                            tool: name.clone(),
442	+                            output: output.content.clone(),
443	+                        })
444	+                        .await;
445	+                    match post.denied {
446	+                        Some(reason) => Err(format!("blocked by PostToolUse hook: {reason}")),
447	+                        None => {
448	+                            let final_json = post.replacement.unwrap_or(output.content);
449	+                            // Redaction is the final transform, after the hooks.
450	+                            Ok(crate::finalize_tool_output(
451	+                                final_json,
452	+                                redact_output,
453	+                                secrets,
454	+                            ))
455	+                        }
456	+                    }
457	+                }
458	+                Err(e) => {
459	+                    tracing::Span::current().record("otel.status_code", "ERROR");
460	+                    Err(e.to_string())
461	+                }
462	+            };
463	+            ToolCallOutcome { call_id, result }
464	+        }
465	+        .instrument(span)
466	+    });
467	+
468	+    let outcomes = match limit {
469	+        None => futures_util::future::join_all(futures).await,
470	+        Some(n) => {
471	+            use futures_util::stream::StreamExt as _;
472	+            let collected: Vec<_> = futures.collect();
473	+            futures_util::stream::iter(collected)
474	+                .buffered(n.get())
475	+                .collect()
476	+                .await
477	+        }
478	+    };
479	+    (outcomes, denied_events.into_inner().unwrap())
480	+}
