486	+        .map(|call| AgentEvent::ToolOutputItem {
487	+            item: Item::ToolResult {
488	+                call_id: call.pending.call_id().to_owned(),
489	+                content: vec![ContentPart::Text {
490	+                    text: NOT_RUN.to_owned(),
491	+                }],
492	+            },
493	+        })
494	+        .collect()
495	+}
