769	+/// Run a root agent that defers its call to `b`, and store the run in a new
770	+/// session. Returns the session.
771	+async fn deferred_session(b: Arc<MockTool>) -> Arc<MemorySession> {
772	+    let session = Arc::new(MemorySession::new());
773	+    let agent = LlmAgent::builder::<()>()
774	+        .name("root")
775	+        .shared_model(MockModel::with_scripts(vec![call_b_turn()]))
776	+        .shared_tool(b as Arc<dyn Tool<()>>)
777	+        .build();
778	+    let ctx = session_ctx(&session).with_deferred_tool_calls(true);
779	+    let mut recorder = SessionRecorder::new("root").with_deferral_slot(ctx.deferral_handle());
780	+    let input = AgentInput::from_user_text("go");
781	+    recorder.record_input(&input.messages);
782	+    let events = run_events(&agent, ctx, input).await;
783	+    assert!(
784	+        matches!(events.last(), Some(AgentEvent::RunDeferred { .. })),
785	+        "{events:?}"
786	+    );
787	+    for ev in &events {
788	+        recorder.observe(ev);
789	+    }
790	+    session.append(&recorder.drain()).await.unwrap();
791	+    session
792	+}
