794	+/// The resume input: the resolution of the one open deferral, then `"next"`.
795	+async fn resume_input(
796	+    session: &MemorySession,
797	+    root: &str,
798	+    resolution: ToolResolution,
799	+) -> (AgentInput, ResumePlan) {
800	+    let events = session.events(None).await.unwrap();
801	+    let snapshot = session.snapshot().await.unwrap();
802	+    let open = open_deferrals(&events);
803	+    assert_eq!(open.len(), 1, "{open:?}");
804	+    let input =
805	+        AgentInput::from_user_text("next").with_resolution(open[0].deferral_id(), resolution);
806	+    let plan = ResumePlan::from_events(&events, &snapshot, root, &input, 8).expect("valid resume");
807	+    (input.with_resume_plan(plan.clone()), plan)
808	+}
