810	+fn text_of(content: &[ContentPart]) -> String {
811	+    content
812	+        .iter()
813	+        .filter_map(|p| match p {
814	+            ContentPart::Text { text } => Some(text.as_str()),
815	+            _ => None,
816	+        })
817	+        .collect()
818	+}
819	+
820	+/// The text of the `ToolOutputItem` for `call_id`.
821	+fn tool_output_text(events: &[AgentEvent], call_id: &str) -> String {
822	+    events
823	+        .iter()
824	+        .find_map(|e| match e {
825	+            AgentEvent::ToolOutputItem {
826	+                item:
827	+                    Item::ToolResult {
828	+                        call_id: id,
829	+                        content,
830	+                    },
831	+            } if id == call_id => Some(text_of(content)),
832	+            _ => None,
833	+        })
834	+        .unwrap_or_else(|| panic!("no ToolOutputItem for {call_id}: {events:?}"))
835	+}
836	+
837	+/// A short label for each event.
838	+fn kind(ev: &AgentEvent) -> String {
839	+    match ev {
840	+        AgentEvent::RunStarted { .. } => "RunStarted".to_owned(),
841	+        AgentEvent::TurnStarted { turn } => format!("TurnStarted({turn})"),
842	+        AgentEvent::ToolOutputItem {
843	+            item: Item::ToolResult { call_id, .. },
844	+        } => format!("ToolOutputItem({call_id})"),
845	+        AgentEvent::PermissionDenied { tool, .. } => format!("PermissionDenied({tool})"),
846	+        AgentEvent::GuardrailTriggered { .. } => "GuardrailTriggered".to_owned(),
847	+        AgentEvent::RunCompleted { .. } => "RunCompleted".to_owned(),
848	+        AgentEvent::RunFailed { error } => format!("RunFailed({error})"),
849	+        _ => "other".to_owned(),
850	+    }
851	+}
852	+
853	+fn kinds(events: &[AgentEvent]) -> Vec<String> {
854	+    events.iter().map(kind).collect()
855	+}
