875	+async fn approved_call_runs_once_with_recorded_args_before_the_new_input() {
876	+    let b = MockTool::new("b", serde_json::json!({ "paid": true }));
877	+    let session = deferred_session(Arc::clone(&b)).await;
878	+    assert!(
879	+        b.invocations().is_empty(),
880	+        "the deferring run must not run b"
881	+    );
882	+    let (input, plan) = resume_input(&session, "root", ToolResolution::Approved).await;
883	+
884	+    let model = RequestLog::with_scripts(vec![text_turn("done")]);
885	+    let agent = resume_agent("root", Arc::clone(&model), Arc::clone(&b)).build();
886	+    let ctx = session_ctx(&session);
887	+    let mut recorder = SessionRecorder::new("root").with_resume_plan(&plan);
888	+    recorder.record_input(&input.messages);
889	+    let events = run_events(&agent, ctx, input).await;
890	+
891	+    let invocations = b.invocations();
892	+    assert_eq!(invocations.len(), 1, "b runs exactly once");
893	+    assert_eq!(invocations[0].0, recorded_args());
894	+
895	+    let ks = kinds(&events);
896	+    assert_eq!(
897	+        ks[..3],
898	+        ["RunStarted", "ToolOutputItem(call_b)", "TurnStarted(0)"],
899	+        "{ks:?}"
900	+    );
901	+    assert_eq!(
902	+        ks.last().map(String::as_str),
903	+        Some("RunCompleted"),
904	+        "{ks:?}"
905	+    );
906	+    assert_eq!(tool_output_text(&events, "call_b"), r#"{"paid":true}"#);
907	+
908	+    let requests = model.requests();
909	+    let messages = &requests[0].messages;
910	+    let n = messages.len();
911	+    assert!(n >= 3, "{messages:?}");
912	+    assert!(
913	+        matches!(&messages[n - 3], Item::ToolCall { call_id, name, .. }
914	+            if call_id == "call_b" && name == "b"),
915	+        "{messages:?}"
916	+    );
917	+    assert!(
918	+        matches!(&messages[n - 2], Item::ToolResult { call_id, .. } if call_id == "call_b"),
919	+        "{messages:?}"
920	+    );
921	+    assert!(
922	+        matches!(&messages[n - 1], Item::UserMessage { content } if text_of(content) == "next"),
923	+        "{messages:?}"
924	+    );
925	+
926	+    // The recorder puts the result before the new input, and the resume
927	+    // closes the deferral.
928	+    for ev in &events {
929	+        recorder.observe(ev);
930	+    }
931	+    let resumed = recorder.drain();
932	+    assert!(
933	+        matches!(&resumed[0], SessionEvent::ToolReturned { call_id, .. } if call_id == "call_b"),
934	+        "{resumed:?}"
935	+    );
936	+    assert!(
937	+        matches!(&resumed[1], SessionEvent::UserMessage { .. }),
938	+        "{resumed:?}"
939	+    );
940	+    session.append(&resumed).await.unwrap();
941	+    assert!(open_deferrals(&session.events(None).await.unwrap()).is_empty());
942	+}
