+        );
+    }
+
+    #[tokio::test]
+    async fn recheck_passes_with_the_flag_off() {
+        let ctx = RunContext::ephemeral(()).with_permission_policy(Arc::new(DeferPolicy));
+        assert!(!ctx.deferred_tool_calls_enabled());
+        assert_eq!(
+            recheck_approved(&ctx, Some(&pay()), "pay", &args()).await,
+            Ok(())
+        );
+    }
+}
