+/// A [`MockModel`] that keeps every request it gets.
+struct RequestLog {
+    inner: Arc<MockModel>,
+    requests: Mutex<Vec<ModelRequest>>,
+}
+
+impl RequestLog {
+    fn with_scripts(scripts: Vec<Vec<ModelEvent>>) -> Arc<Self> {
