+async fn run_events(
+    agent: &impl Agent<()>,
+    ctx: RunContext<()>,
+    input: AgentInput,
+) -> Vec<AgentEvent> {
+    agent
+        .run(ctx, input)
+        .await
+        .expect("run starts")
+        .collect()
+        .await
